  const given = hintLabels.split(',').map((item) => item.trim());
  const [choose, insert, close] = given.length === 3 && given.every(Boolean) ? given : ['choose', 'insert', 'close'];
  // BlockMenu draws catalog rows by label (an insert type's icon, description, shortcut and group,
  // or a block action's key) or `id:text[:description]` (that row showing `text`, with no
  // description unless given). `group:id:text` renames a group heading; any other entry is plain.
  return h(ui.BlockMenu, { label, kind, placement, items: names, activeItem: active ?? names[0] },
    hints && h(ui.BlockMenuFooter, null, h('span', null, h(ui.BlockKbd, null, '↑↓'), ` ${choose}`),
