const choose = (value, allowed, fallback) => (allowed.includes(value) ? value : fallback);

export default ({ React, ui }) =>
  function ImageBlockTag(props) {
    const images = list(props.images)
      .filter((item) => item && typeof item.src === 'string')
      .map((item) => ({
        src: item.src,
        alt: text(item.alt) ?? '',
